// Erreur d'un workflow → événement normalisé (avec la vidéo concernée et le corps complet de l'erreur)
const e = $('Erreur').first().json;
const x = $input.first().json || {};
const run = (x.data && x.data.resultData) || {};
const noeud = e.execution?.lastNodeExecuted || run.lastNodeExecuted || '?';
let err = e.execution?.error || {};
try { const r = (run.runData?.[noeud] || []).slice(-1)[0]; if (r && r.error) err = { ...err, ...r.error }; } catch (_) {}
// vidéo concernée : d'abord la requête qui a planté, sinon le premier nœud qui porte un video_id
let video = null;
const prend = j => j && (j.titre_short || j.titre) ? { id: j.video_id || '', titre: j.titre_short || j.titre } : null;
try { video = prend((err.context?.request?.body?.data || [])[0]); } catch (_) {}
for (const runs of Object.values(run.runData || {})) {
  if (video) break;
  for (const r of runs) {
    const j = r?.data?.main?.[0]?.[0]?.json;
    video = prend(j) || prend(j?.body) || prend((j?.data || [])[0]);
    if (video) break;
  }
}
const brut = [err.message, err.description, ...(err.messages || []), err.context?.data ? JSON.stringify(err.context.data) : '']
  .filter(Boolean).filter((v, i, a) => a.indexOf(v) === i).join('\n');
return [{ json: { evenements: [{ type: 'echec', origine: 'erreur', workflow: e.workflow?.name || '?', noeud,
  video, plateforme: '', brut: brut || JSON.stringify(err).slice(0, 2000), exec_id: e.execution?.id || '', quand: new Date().toISOString() }] } }];

const b = $('Signalement').first().json.body || {};
const evs = (Array.isArray(b.evenements) ? b.evenements : [b]).filter(v => v && v.type);
return [{ json: { evenements: evs.map(v => ({ quand: new Date().toISOString(), ...v })) } }];

// ---------- outils ----------
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const masque = s => String(s ?? '')
  .replace(/(access_token|api_key|key|sig|token|secret|password|client_secret)=([^&\s"'\\]+)/gi, '$1=***')
  .replace(/Bearer\s+[A-Za-z0-9._\-]+/g, 'Bearer ***')
  .replace(/sk-[A-Za-z0-9_\-]{10,}/g, 'sk-***')
  .replace(/\b\d{8,10}:[A-Za-z0-9_\-]{30,}\b/g, '***')
  .replace(/EAA[A-Za-z0-9]{20,}/g, 'EAA***');
const TZ = { timeZone: 'Europe/Paris' };
const hm = d => new Date(d).toLocaleTimeString('fr-FR', { ...TZ, hour: '2-digit', minute: '2-digit' });
const jhm = d => { const t = new Date(d); const j = t.toLocaleDateString('fr-FR', { ...TZ, day: '2-digit', month: '2-digit' });
  return (j === new Date().toLocaleDateString('fr-FR', { ...TZ, day: '2-digit', month: '2-digit' }) ? '' : j + ' ') + hm(t); };
const H = 3600e3, now = Date.now();
const prochain9h = () => { // quota YouTube remis à zéro à minuit heure du Pacifique
  const pac = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Los_Angeles' }));
  const m = new Date(pac); m.setHours(24, 10, 0, 0); return now + (m - pac); };
const NOMS = { youtube: 'YouTube', meta: 'Facebook + Instagram', facebook: 'Facebook', instagram: 'Instagram' };

