const CONTEXTE = {
  'VEILLE': { impact: "Les nouvelles vidéos de ce passage ne sont ni enregistrées ni proposées, et aucun Short n'est lancé automatiquement.",
              fait: 'La veille repasse automatiquement à la prochaine heure.' },
  'PRODUCTION': { impact: v => `Le Short ${v ? '« ' + v + ' » ' : ''}n'est pas monté : il ne sera pas publié.`, fait: "Rien : la production n'est pas relancée automatiquement." },
  'PUBLICATION': { impact: v => `Le Short ${v ? '« ' + v + ' » ' : ''}n'est publié nulle part.`, fait: "Rien : la publication n'est pas relancée automatiquement." },
  'ZAPPING': { impact: "Le zapping du jour n'est pas produit.", fait: 'Rien : nouvel essai demain.' },
  'APPRENTISSAGE': { impact: "Le bilan du jour et les leçons ne sont pas mis à jour (aucun effet sur les publications).", fait: 'Nouvel essai au prochain bilan.' },
};
const ctx = wf => CONTEXTE[Object.keys(CONTEXTE).find(k => String(wf).toUpperCase().startsWith(k))] || { impact: "Ce workflow s'est arrêté avant la fin.", fait: 'Rien.' };

function diagnostiquer(ev) {
  const brut = String(ev.brut || '');
  const r = R.find(x => x.test.test(brut) && (!x.plateforme || !ev.plateforme || x.plateforme === ev.plateforme ||
              (x.plateforme === 'meta' && ['facebook', 'instagram'].includes(ev.plateforme)) || (ev.plateforme === 'meta' && ['facebook', 'instagram'].includes(x.plateforme))));
  const c = ctx(ev.workflow);
  const vt = ev.video && ev.video.titre;
  const base = { impact: ev.impact || (typeof c.impact === 'function' ? c.impact(vt) : c.impact), fait: c.fait };
  if (r && r.g === 'orange' && !r.pause_h && !r.pause_jusqu && !/VEILLE/i.test(ev.workflow))
    return { ...base, ...r, g: 'rouge', plateforme: r.plateforme || ev.plateforme || '', signature: r.cle + '|' + (r.plateforme || ev.plateforme || ev.workflow),
      action: 'Ce circuit ne réessaie pas tout seul : demande à Claude de relancer' + (vt ? ' « ' + vt + ' »' : ' cette étape') + '.' };
  if (r) return { ...base, ...r, plateforme: ev.plateforme && ev.plateforme !== r.plateforme && r.plateforme === 'meta' ? 'meta' : (r.plateforme || ev.plateforme || ''),
                  signature: r.cle + '|' + (r.plateforme || ev.plateforme || ev.workflow) };
  const premiere = (brut.split('\n').find(Boolean) || 'erreur inconnue').slice(0, 160);
  return { ...base, cle: 'inconnu', plateforme: ev.plateforme || '', g: ev.plateforme ? 'rouge' : (/VEILLE/i.test(ev.workflow) ? 'orange' : 'rouge'),
    signature: 'inconnu|' + ev.workflow + '|' + ev.noeud + '|' + premiere.replace(/[0-9]+/g, '#').slice(0, 60),
    titre: 'Erreur inattendue' + (ev.plateforme ? ' sur ' + NOMS[ev.plateforme] : ''), quoi: `L'étape « ${ev.noeud} » a échoué : ${premiere}`,
    inconnue: true, pistes: ['Lire le détail technique ci-dessous (message renvoyé par le service)', 'Vérifier si le service appelé est en panne ou a changé ses règles',
      'Vérifier une modification récente de ce workflow'],
    action: 'Si ça se répète, transmets cette alerte à Claude.' };
}

function texte(row, d, ev, escalade) {
  const G = { rouge: '🔴 <b>ACTION REQUISE</b>', orange: '🟠 <b>Le système réessaie seul</b>', blanc: '⚪ <b>Info</b>' };
  const g = escalade ? 'rouge' : d.g;
  const vids = JSON.parse(row.videos || '[]');
  const L = [`${G[g]} — ${esc(d.titre)}`,
    row.nb > 1 ? `<i>En échec depuis ${jhm(row.premier)} · ${row.nb} échecs (dernier à ${hm(row.dernier)})</i>` : `<i>${jhm(row.dernier)}</i>`, '',
    `📌 <b>Ce qui s'est passé :</b> ${esc(d.quoi)}`,
    `📍 <b>Où :</b> ${esc(ev.workflow)} › ${esc(ev.noeud)}${ev.video && ev.video.titre ? ' · « ' + esc(ev.video.titre) + ' »' : ''}`,
    `💥 <b>Impact :</b> ${esc(d.impact)}`];
  if (d.certain) L.push(`🔎 <b>Cause :</b> ${esc(d.certain)}`);
  else if (d.causes) L.push('🔎 <b>Causes possibles</b> (de la plus à la moins probable) :', ...d.causes.map((c, i) => `  ${i + 1}. ${esc(c)}`));
  else L.push('🔎 <b>Cause non identifiée.</b> Pistes à vérifier :', ...d.pistes.map((c, i) => `  ${i + 1}. ${esc(c)}`));
  L.push(`👉 <b>Ce que tu dois faire :</b> ${esc(escalade ? 'Ça échoue à chaque passage : transmets cette alerte à Claude.' : d.action)}`);
  const fait = [];
  if (ev.fait) fait.push(ev.fait);
  if (row.suspendue_jusqu && Date.parse(row.suspendue_jusqu) > now)
    fait.push(`${NOMS[row.plateforme] || row.plateforme} mis en pause jusqu'à ${jhm(row.suspendue_jusqu)} : les Shorts prévus d'ici là y sont sautés (pas d'échecs en série), puis le système réessaie tout seul.`);
  if (!fait.length) fait.push(d.fait);
  L.push(`🤖 <b>Déjà fait par le système :</b> ${esc(fait.join(' '))}`);
  if (vids.length > 1) {
    L.push('🎬 <b>Shorts concernés :</b>', ...vids.slice(-8).map(v => `  • ${esc(v.h)} « ${esc(v.t)} » — ${v.e === 'saute' ? 'sauté (pause), à reprendre' : 'échec'}`));
    const sautes = vids.filter(v => v.e === 'saute').length;
    if (sautes) L.push(`  <i>${sautes} Short(s) sauté(s) pendant la pause.</i>`);
  }
  const corps = L.join('\n'), tete = '\n\n🧾 <b>Détail technique</b>' + (ev.exec_id ? ` (exécution ${esc(ev.exec_id)})` : '') + ' :\n';
  const place = Math.max(200, 3900 - corps.length - tete.length - 20);
  return corps + tete + `<pre>${esc(masque(ev.brut).slice(0, Math.min(1400, Math.floor(place / 1.2))))}</pre>`;
}
const brutTexte = t => t.replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

// ---------- regroupement ----------
const rows = ($('Lire alertes actives').first().json.data || []).map(r => ({ ...r }));
const evs = $('Événements').first().json.evenements || [];
const sorties = [], parSig = new Map();
for (const ev of evs) {
  ev.workflow = ev.workflow || '?'; ev.noeud = ev.noeud || '?';
  if (ev.type === 'retabli') {
    for (const row of rows.filter(r => r.statut === 'active' && r.plateforme && (r.plateforme === ev.plateforme || (r.plateforme === 'meta' && ['facebook', 'instagram'].includes(ev.plateforme))))) {
      row.statut = 'resolue';
      const vids = JSON.parse(row.videos || '[]'), sautes = vids.filter(v => v.e === 'saute');
      const t = [`✅ <b>${esc(NOMS[row.plateforme] || row.plateforme)} refonctionne</b>`,
        `Panne du ${jhm(row.premier)} au ${jhm(now)} · ${row.nb} échec(s).`,
        `Premier Short publié normalement : « ${esc(ev.video && ev.video.titre || '?')} ».`,
        ...(vids.length ? ['', `🎬 <b>Shorts non publiés sur ${esc(NOMS[row.plateforme] || row.plateforme)} pendant la panne</b> (à reprendre à la main si tu les veux) :`,
          ...vids.slice(-12).map(v => `  • ${esc(v.h)} « ${esc(v.t)} »${v.e === 'saute' ? ' (sauté)' : ''}`)] : [])].join('\n');
      sorties.push({ action: 'retabli', texte: t, texte_brut: brutTexte(t), signature: row.signature,
        data: { statut: 'resolue', suspendue_jusqu: null } });
    }
    continue;
  }
  if (ev.type === 'saute') {
    const row = rows.filter(r => r.statut === 'active' && r.plateforme === ev.plateforme).sort((a, b) => Date.parse(b.dernier) - Date.parse(a.dernier))[0];
    if (!row) continue;
    const vids = JSON.parse(row.videos || '[]'); vids.push({ t: ev.video && ev.video.titre || '?', e: 'saute', h: jhm(now) }); row.videos = JSON.stringify(vids.slice(-30));
    const det = JSON.parse(row.detail || '{}'), d = diagnostiquer(det.ev || ev);
    const t = texte(row, d, det.ev || ev, det.escalade);
    const prev = parSig.get(row.signature);
    parSig.set(row.signature, prev ? { ...prev, texte: t, texte_brut: brutTexte(t), data: { ...prev.data, videos: row.videos } }
      : { action: row.message_id ? 'maj' : 'nouveau', creer: false, texte: t, texte_brut: brutTexte(t), message_id: row.message_id, signature: row.signature, data: { videos: row.videos } });
    continue;
  }
  // échec
  const d = diagnostiquer(ev);
  let row = rows.find(r => r.statut === 'active' && r.signature === d.signature && now - Date.parse(r.dernier) < 24 * H);
  const vid = { t: ev.video && ev.video.titre || '', e: 'echec', h: jhm(now) };
  let action = 'maj', escalade = false;
  if (row) {
    row.nb = (+row.nb || 1) + 1; row.dernier = new Date(now).toISOString();
    const det = JSON.parse(row.detail || '{}');
    escalade = d.g === 'orange' && !d.pause_h && !d.pause_jusqu && row.nb >= 3;
    if (escalade && !det.escalade) action = 'nouveau'; // passage en rouge : nouveau message (notifié)
  } else {
    action = 'nouveau';
    row = { signature: d.signature, plateforme: d.plateforme, workflow: ev.workflow, gravite: d.g, statut: 'active', premier: new Date(now).toISOString(),
            dernier: new Date(now).toISOString(), nb: 1, videos: '[]', _nouvelle: true };
    rows.push(row);
  }
  if (!row._nouvelle && !escalade) action = 'maj';
  if (vid.t) { const v = JSON.parse(row.videos || '[]'); v.push(vid); row.videos = JSON.stringify(v.slice(-30)); }
  // pause de la plateforme : cause connue qui l'exige, ou 2e échec d'affilée d'une cause inconnue
  const pause = d.pause_jusqu ? d.pause_jusqu() : d.pause_h ? now + d.pause_h * H : (row.plateforme && row.nb >= 2 ? now + H : null);
  if (row.plateforme && pause) row.suspendue_jusqu = new Date(pause).toISOString();
  row.gravite = escalade ? 'rouge' : d.g;
  row.detail = JSON.stringify({ ev: { ...ev, brut: String(ev.brut || '').slice(0, 3000) }, escalade });
  const data = { nb: row.nb, dernier: row.dernier, videos: row.videos, gravite: row.gravite, detail: row.detail, suspendue_jusqu: row.suspendue_jusqu || null };
  const t = texte(row, d, ev, escalade);
  const prev = parSig.get(row.signature);
  const creer = !!row._nouvelle || !!(prev && prev.creer);
  // pas de message connu à modifier → on en envoie un nouveau
  if (!creer && !row.message_id) action = 'nouveau';
  parSig.set(row.signature, { action: creer || action === 'nouveau' || (prev && prev.action === 'nouveau') ? 'nouveau' : 'maj', creer, texte: t, texte_brut: brutTexte(t),
    message_id: row.message_id, signature: row.signature,
    data: creer ? { signature: row.signature, plateforme: row.plateforme, workflow: row.workflow, statut: 'active', premier: row.premier, ...data } : data });
}
return [...parSig.values(), ...sorties].map(s => ({ json: s }));
